import * as T from './vendor/three.module.min.js';
import {preloadGarden81 as preloadOld,gardenMaterials81 as oldMaterials} from './tiki-garden-materials-v81.js';
const cache=new Map(),ROOT=new URL('./textures/tiki-garden-v86/',import.meta.url);
const maps=['basecolor','normal','roughness','height','ao'];
const files=[...['lava','flagstone','ceiling'].flatMap(n=>maps.map(c=>`surfaces/${n}-${c}.webp`)),...['shutter','lauhala','reed'].flatMap(n=>['basecolor','normal','roughness','ao'].map(c=>`bar/${n}-${c}.webp`)),'bar/notice.webp',...Array.from({length:4},(_,i)=>`mural-${i+1}.webp`),...['banana','monstera','bromeliad','boston-fern'].map(n=>`plants/${n}.webp`),...['bar','mural','wood'].flatMap(n=>['basecolor','normal','roughness','height'].map(c=>`sculpture/${n}-${c}.webp`)),...['basecolor','normal','roughness','ao'].map(c=>`../tiki-garden-v85/walls/lava-rock-${c}.webp`),'../tiki-garden-v85/plants/runtime/multicolored-croton-1024.webp','../tiki-garden-v85/plants/runtime/pineapple-growing-plant-1024.webp','../npc-v75/ochre-water-streaks-128.png'];
export async function preloadGarden81(report=()=>{}){await preloadOld(p=>report(p*.42));let cursor=0,done=0;const loader=new T.TextureLoader();await Promise.all(Array.from({length:4},async()=>{while(cursor<files.length){const f=files[cursor++];if(!cache.has(f)){const t=await loader.loadAsync(new URL(f,ROOT).href);t.colorSpace=/normal|roughness|height|ao/.test(f)?T.NoColorSpace:T.SRGBColorSpace;const repeat=/surfaces|bar\/(shutter|lauhala|reed)|sculpture\/wood|lava-rock/.test(f);t.wrapS=t.wrapT=repeat?T.RepeatWrapping:T.ClampToEdgeWrapping;t.anisotropy=4;t.minFilter=T.LinearMipmapLinearFilter;cache.set(f,t);}report(.42+.58*++done/files.length);}}));}
// Local baked occlusion describes the enclosed vestibule. It affects reflected
// light only, preserving the tiny physical lamp glow inside the dark corridor.
function porchOcclusion(mat){const previous=mat.onBeforeCompile;mat.onBeforeCompile=s=>{previous?.(s);s.vertexShader=s.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 nookWorld;').replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nnookWorld=(modelMatrix*vec4(transformed,1.)).xyz;');s.fragmentShader=s.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 nookWorld;').replace('#include <aomap_fragment>',`#include <aomap_fragment>
 float nookEnclosure=smoothstep(7.5,10.6,nookWorld.z)*(1.-smoothstep(1.2,1.9,abs(nookWorld.x)));
 reflectedLight.indirectDiffuse*=mix(1.,.10,nookEnclosure);reflectedLight.indirectSpecular*=mix(1.,.12,nookEnclosure);
 reflectedLight.directDiffuse*=mix(1.,.23,nookEnclosure);reflectedLight.directSpecular*=mix(1.,.25,nookEnclosure);
`);};mat.customProgramCacheKey=()=> 'v86-enclosed-porch-'+mat.name;}
export function gardenMaterials81(){const base=oldMaterials(),m=base.m,tx=f=>{const t=cache.get(f);if(!t)throw Error('V86 missing '+f);return t;};
 const pbr=(name,folder,options={})=>new T.MeshStandardMaterial({name:'V86 '+name,map:tx(`${folder}/${name}-basecolor.webp`),normalMap:tx(`${folder}/${name}-normal.webp`),roughnessMap:tx(`${folder}/${name}-roughness.webp`),normalScale:new T.Vector2(.65,.65),roughness:1,metalness:0,...options});
 m.wall=new T.MeshStandardMaterial({name:'V86 projected matte stone envelope',map:tx('../tiki-garden-v85/walls/lava-rock-basecolor.webp'),normalMap:tx('../tiki-garden-v85/walls/lava-rock-normal.webp'),roughnessMap:tx('../tiki-garden-v85/walls/lava-rock-roughness.webp'),roughness:1,metalness:0,normalScale:new T.Vector2(.70,.70),aoMap:tx('../tiki-garden-v85/walls/lava-rock-ao.webp'),aoMapIntensity:.55});
 m.lava=pbr('lava','surfaces',{normalScale:new T.Vector2(1.35,1.35),displacementMap:tx('surfaces/lava-height.webp'),displacementScale:.055,displacementBias:-.025,aoMap:tx('surfaces/lava-ao.webp'),aoMapIntensity:.62,roughness:1});
 const rockCompile=m.boulder.onBeforeCompile;m.lava.onBeforeCompile=s=>{rockCompile(s);s.fragmentShader=s.fragmentShader.replace('float gardenWet=1.-smoothstep(-.12,.26,gardenWorld.y);','float gardenWet=0.;');};m.lava.customProgramCacheKey=()=> 'v86-lava-triplanar-dry-matte';m.rock=m.lava;
 m.wood=pbr('wood','sculpture',{normalScale:new T.Vector2(.65,.65),roughness:1});m.barWood=m.wood.clone();m.barWood.name='V86 polished solid timber countertop';m.barWood.roughness=.42;m.barWood.color.setHex(0xb49d76);
 m.reed=pbr('reed','bar',{normalScale:new T.Vector2(.67,.67),aoMap:tx('bar/reed-ao.webp'),aoMapIntensity:.4});m.bamboo=m.reed.clone();m.bamboo.name='V86 physical honey bamboo poles';m.bamboo.roughness=.83;m.bamboo.normalScale.set(.30,.30);
 m.lauhala=pbr('lauhala','bar',{normalScale:new T.Vector2(.90,.90),aoMap:tx('bar/lauhala-ao.webp'),aoMapIntensity:.45});m.shutter=pbr('shutter','bar',{normalScale:new T.Vector2(.50,.50),metalness:.45,roughness:.82,aoMap:tx('bar/shutter-ao.webp'),aoMapIntensity:.6});m.shutterTrim=m.shutter.clone();m.shutterTrim.name='V86 steel curtain tracks';m.shutterTrim.color.setHex(0x6a6d68);
 m.notice=new T.MeshStandardMaterial({name:'V86 yellowed framed paper',map:tx('bar/notice.webp'),roughness:1});
 m.ceiling=pbr('ceiling','surfaces',{normalScale:new T.Vector2(.18,.18),roughness:1,emissive:0xd8d4c4,emissiveIntensity:.035});m.ceilingTrim=m.ceiling.clone();m.ceilingTrim.name='V86 cream painted thin ceiling T rail';m.ceilingTrim.color.setHex(0xd0cbb9);m.ceilingTrim.normalScale.set(.10,.10);
 m.stonePath=pbr('flagstone','surfaces',{normalScale:new T.Vector2(1.05,1.05),roughness:.92,aoMap:tx('surfaces/flagstone-ao.webp'),aoMapIntensity:.30});
 m.roofUnderside=m.wood.clone();m.roofUnderside.name='V86 dark enclosed thatch soffit';m.roofUnderside.color.setHex(0x524a39);m.roofUnderside.side=T.DoubleSide;m.soil=m.lava.clone();m.soil.name='V86 planted bed soil';m.soil.color.setHex(0x34382a);m.soil.displacementScale=0;
 m.rim=m.wall.clone();m.rim.name='V86 stone cornice';m.frosted=new T.MeshStandardMaterial({name:'Decorative frosted safety panes',color:0xb3bdae,roughness:.86,metalness:.02,normalMap:base.texture('surfaces','wall','normal'),normalScale:new T.Vector2(.042,.042),emissive:0xa5b7a4,emissiveIntensity:.045});
 m.plantPot=new T.MeshStandardMaterial({name:'Old green glazed plant pot',color:0x305e4a,roughness:.31,metalness:0,normalMap:tx('sculpture/wood-normal.webp'),normalScale:new T.Vector2(.035,.035)});
 m.lampGlass=new T.MeshStandardMaterial({name:'Frosted amber practical globe',color:0xc5a475,emissive:0xffa947,emissiveIntensity:1.1,roughness:.6});
 for(let i=1;i<=4;i++)m['rainforest'+i]=new T.MeshStandardMaterial({name:'V86 recessed painted island mural '+i,map:tx(`mural-${i}.webp`),roughness:1,metalness:0,emissiveMap:tx(`mural-${i}.webp`),emissive:0xffffff,emissiveIntensity:.04});
 for(const [name,file]of Object.entries({banana:'plants/banana.webp',monstera:'plants/monstera.webp',bromeliad:'plants/bromeliad.webp',fern:'plants/boston-fern.webp',croton:'../tiki-garden-v85/plants/runtime/multicolored-croton-1024.webp',pineapple:'../tiki-garden-v85/plants/runtime/pineapple-growing-plant-1024.webp'})){m[name]=new T.MeshStandardMaterial({name:'V86 waxy photographic foliage '+name,map:tx(file),alphaTest:.37,side:T.DoubleSide,roughness:.64,metalness:0});m[name].forceSinglePass=true;m[name].onBeforeCompile=s=>{s.fragmentShader=s.fragmentShader.replace('#include <emissivemap_fragment>',`#include <emissivemap_fragment>\nvec3 leafLight=normalize(mat3(viewMatrix)*vec3(.49,.53,-.68));float leafThrough=pow(max(0.,dot(-normal,leafLight)),2.);totalEmissiveRadiance+=diffuseColor.rgb*leafThrough*.075;`);};m[name].customProgramCacheKey=()=> 'v86-thin-leaf-backscatter';}
 for(let i=1;i<=2;i++){const name=i===1?'bar':'mural';m['idol'+i]=pbr(name,'sculpture',{name:'V86 carved totem face '+i,normalScale:new T.Vector2(.72,.72),displacementMap:tx(`sculpture/${name}-height.webp`),displacementScale:.018,displacementBias:-.009,alphaTest:.06,side:T.DoubleSide});}
 for(const key of['wall','wood','bamboo','reed','door','roofUnderside','stonePath','idol1','idol2'])porchOcclusion(m[key]);
 return{...base,m,textures:[...base.textures,...cache.values()],streamTexture:tx('../npc-v75/ochre-water-streaks-128.png')};
}
